  "code": """"LightGBM with target encoding for high-cardinality categoricals."""

from __future__ import annotations

import pandas as pd
from lightgbm import LGBMClassifier


def fit_predict(train_csv: str, test_rows: list[dict[str, str]]) -> list[float]:
    train = pd.read_csv(train_csv)
    y = train.pop("y").astype(int)
    test = pd.DataFrame(test_rows, columns=train.columns)

    # Align numeric columns
    for name in train.columns:
        if pd.api.types.is_numeric_dtype(train[name]):
            test[name] = pd.to_numeric(test[name]).astype(float)
        else:
            # Union categories between train and test
            all_cats = pd.Categorical(pd.concat([train[name], test[name]], ignore_index=True)).categories
            train[name] = pd.Categorical(train[name], categories=all_cats)
            test[name] = pd.Categorical(test[name], categories=all_cats)

    # High-cardinality categorical columns
    high_card_cols = ["native_country", "occupation", "workclass"]

    # Global mean for smoothing
    global_mean = y.mean()

    def compute_target_encoding(source_df, col):
        """Compute smoothed target encoding for a categorical column."""
        grouped = source_df.groupby(col)["y_mean"][0].aggregate(lambda x: (x.sum(), x.count()))
        counts = {}
        sums = {}
        for cat, (s, c) in grouped.items():
            sums[cat] = s
            counts[cat] = c
        return sums, counts

    def encode_column(df, col, alpha=30.0):
        """Add smoothed target encoding column."""
        grouped = df.groupby(col).apply(lambda g: {'sum': g['y'].sum(), 'count': len(g)}).unstack(fill_value=0)
        result = {}
        for cat in df[col].unique():
            s = grouped.loc[cat, 'sum'] if cat in grouped.index else 0
            c = grouped.loc[cat, 'count'] if cat in grouped.index else 0
            result[cat] = (s + global_mean * alpha) / (c + alpha)
        return result

    # Compute encodings from training data only
    encoders = {}
    for col in high_card_cols:
        if col in train.columns and train[col].nunique() >= 5:
            encoders[col] = encode_column(train, col, alpha=30.0)

    # Add encoded columns to train
    X_train = train.copy()
    for col, encoder in encoders.items():
        X_train[f"{col}_enc"] = X_train[col].map(encoder).fillna(global_mean)

    # Add encoded columns to test
    X_test = test.copy()
    for col, encoder in encoders.items():
        X_test[f"{col}_enc"] = X_test[col].map(encoder).fillna(global_mean)

    # Fit model
    model = LGBMClassifier(random_state=20261114, n_jobs=1, verbosity=-1)
    model.fit(X_train, y)

    return model.predict_proba(X_test)[:, 1].tolist()
